  'If_this_field_is_active_customers_get_the_OTP_through_Firebase.' => 'यदि यह फ़ील्ड सक्रिय है तो ग्राहकों को फायरबेस के माध्यम से ओटीपी मिलता है।',
  'messages.firebase_otp_verification' => 'messages.firebase ओटीपी सत्यापन',
  'firebase_otp_verification' => 'फायरबेस ओटीपी सत्यापन',
  'Want to enable Firebase OTP Verification ' => 'फायरबेस ओटीपी सत्यापन सक्षम करना चाहते हैं ',
  'Want to disable Firebase OTP Verification ' => 'फायरबेस ओटीपी सत्यापन को अक्षम करना चाहते हैं ',
  'With Firebase OTP enabled  verification codes will be sent through Firebase.' => 'फायरबेस ओटीपी सक्षम सत्यापन कोड फायरबेस के माध्यम से भेजे जाएंगे।',
  'Enable Firebase OTP means users will not receive verification codes through Email or SMS Although those methods are activated.' => 'फायरबेस ओटीपी सक्षम करने का मतलब है कि उपयोगकर्ताओं को ईमेल या एसएमएस के माध्यम से सत्यापन कोड प्राप्त नहीं होंगे, हालांकि वे तरीके सक्रिय हैं।',
  'If you disable Firebase OTP  users will no longer receive verification codes via Firebase. You must activate Email or SMS verification as an alternative' => 'यदि आप फायरबेस ओटीपी को अक्षम करते हैं तो उपयोगकर्ताओं को फायरबेस के माध्यम से सत्यापन कोड प्राप्त नहीं होंगे। आपको विकल्प के रूप में ईमेल या एसएमएस सत्यापन सक्रिय करना होगा',
  'For configuring OTP in the Firebase  you must create a Firebase project first.' => 'फायरबेस में ओटीपी कॉन्फ़िगर करने के लिए आपको पहले एक फायरबेस प्रोजेक्ट बनाना होगा।',
  'Note: Enable Firebase OTP means users will not receive verification codes through Email or SMS although those methods are activated.' => 'नोट: फायरबेस ओटीपी सक्षम करने का मतलब है कि उपयोगकर्ताओं को ईमेल या एसएमएस के माध्यम से सत्यापन कोड प्राप्त नहीं होंगे, हालांकि वे तरीके सक्रिय हैं।',
  'If you disable Firebase OTP  users will no longer receive verification codes via Firebase. You must activate Email or SMS verification as an alternative.' => 'यदि आप फायरबेस ओटीपी को अक्षम करते हैं तो उपयोगकर्ताओं को फायरबेस के माध्यम से सत्यापन कोड प्राप्त नहीं होंगे। आपको विकल्प के रूप में ईमेल या एसएमएस सत्यापन सक्रिय करना होगा।',
  'For configuring OTP in the Firebase  you must create a Firebase project first. If you haven’t created any project for your application yet  please create a project first.' => 'फायरबेस में ओटीपी कॉन्फ़िगर करने के लिए आपको पहले एक फायरबेस प्रोजेक्ट बनाना होगा। यदि आपने अभी तक अपने एप्लिकेशन के लिए कोई प्रोजेक्ट नहीं बनाया है तो कृपया पहले एक प्रोजेक्ट बनाएं।',
  'Now go to the' => 'अब पर जाएँ',
  'Get started with the project and go to the Sign-in method tab.' => 'प्रोजेक्ट के साथ आरंभ करें और साइन-इन विधि टैब पर जाएं।',
  'Ensure to enable the Phone method and press save.' => 'फ़ोन विधि को सक्षम करना सुनिश्चित करें और सेव दबाएँ।',
  'In Message field you can’t change the Customer Name  Parcel ID & Tracking Link. They will automatically generate. You can only edit other text.' => 'संदेश फ़ील्ड में आप ग्राहक का नाम पार्सल आईडी और ट्रैकिंग लिंक नहीं बदल सकते। वे स्वचालित रूप से उत्पन्न होंगे. आप केवल अन्य पाठ को संपादित कर सकते हैं.',
  'If you disable Firebase OTP  users will no longer receive verification codes via Firebase. You must activate SMS verification as an alternative.' => 'यदि आप फायरबेस ओटीपी को अक्षम करते हैं तो उपयोगकर्ताओं को फायरबेस के माध्यम से सत्यापन कोड प्राप्त नहीं होंगे। आपको विकल्प के रूप में एसएमएस सत्यापन सक्रिय करना होगा।',
  'Note: Enable Firebase OTP means users will not receive verification codes through SMS although those methods are activated.' => 'नोट: फायरबेस ओटीपी सक्षम करने का मतलब है कि उपयोगकर्ताओं को एसएमएस के माध्यम से सत्यापन कोड प्राप्त नहीं होंगे, हालांकि वे तरीके सक्रिय हैं।',
  'Firebase OTP Setup' => 'फायरबेस ओटीपी सेटअप',
  'They will automatically generate. You can only edit other text.' => 'वे स्वचालित रूप से उत्पन्न होंगे. आप केवल अन्य पाठ को संपादित कर सकते हैं.',
  'In Message field you can’t change the' => 'संदेश फ़ील्ड में आप इसे नहीं बदल सकते',
