  'Do you want to Approved the refund request  For this parcel customer wants $250.00 refunded for the parcel damage.' => 'क्या आप इस पार्सल के लिए रिफंड अनुरोध को मंजूरी देना चाहते हैं, ग्राहक पार्सल क्षति के लिए $250.00 रिफंड चाहता है।',
