  'You will get a Popup for Setting up Extra Fare & Reason.' => 'आपको अतिरिक्त किराया और कारण निर्धारित करने के लिए एक पॉपअप मिलेगा।',
  'Allow notifications to be sent to users when the privacy policy is updated' => 'गोपनीयता नीति अद्यतन होने पर उपयोगकर्ताओं को सूचनाएं भेजने की अनुमति दें',
  'Allow notifications to be sent to users when the Legals is updated' => 'कानूनी अद्यतन होने पर उपयोगकर्ताओं को सूचनाएं भेजने की अनुमति दें',
  'Allow notifications to be sent to users when the Terms & Conditions is updated' => 'नियम एवं शर्तें अपडेट होने पर उपयोगकर्ताओं को सूचनाएं भेजने की अनुमति दें',
  'f want to set up separately for each zone  then follow the instructions' => 'यदि आप प्रत्येक जोन के लिए अलग से सेटअप करना चाहते हैं तो निर्देशों का पालन करें',
  'Enabling this option will apply the extra fare to all rides and parcels across this specific zone when weather conditions change or there is heavy traffic.' => 'इस विकल्प को सक्षम करने से मौसम की स्थिति बदलने या भारी यातायात होने पर इस विशिष्ट क्षेत्र में सभी सवारी और पार्सल पर अतिरिक्त किराया लागू होगा।',
  'When Allow Extra Fare Setup - All Zone  the Extra Fare(%) will be applicable for all the active zones.' => 'जब अतिरिक्त किराया सेटअप की अनुमति दी जाती है - सभी जोन, अतिरिक्त किराया (%) सभी सक्रिय क्षेत्रों के लिए लागू होगा।',
  'Set the percentage of extra fare to be added to the total fare' => 'कुल किराये में जोड़े जाने वाले अतिरिक्त किराये का प्रतिशत निर्धारित करें',
  'Enabling this option will apply the extra fare to all rides and parcels across All Zones when the weather conditions change or heavy traffic.' => 'इस विकल्प को सक्षम करने से मौसम की स्थिति बदलने या भारी ट्रैफ़िक होने पर सभी ज़ोन में सभी सवारी और पार्सल पर अतिरिक्त किराया लागू होगा।',
  'Are you Sure to turn off Extra Fare for this Zones' => 'क्या आप निश्चित रूप से इस क्षेत्र के लिए अतिरिक्त किराया बंद कर देंगे',
  'Once you turn off this option  Customers will not be required to pay any Extra Fares in this Zone' => 'एक बार जब आप इस विकल्प को बंद कर देंगे तो ग्राहकों को इस क्षेत्र में कोई अतिरिक्त किराया नहीं देना होगा',
  'Are you Sure to turn off Extra Fare for All Zones' => 'क्या आप निश्चित रूप से सभी ज़ोन के लिए अतिरिक्त किराया बंद कर देंगे?',
  'Setup the minimum App versions in which the system will be compatible' => 'न्यूनतम ऐप संस्करण सेट करें जिसमें सिस्टम संगत होगा',
  'Hear you can write a massage body. Customer Name  Parcel ID & Tracking link will generate automatically for each individual parcel.' => 'सुना है आप मसाज बॉडी लिख सकते हैं। ग्राहक का नाम पार्सल आईडी और ट्रैकिंग लिंक प्रत्येक व्यक्तिगत पार्सल के लिए स्वचालित रूप से उत्पन्न होगा।',
  'Enabling this option will send the parcel tracking link to the customer via SMS when they place any parcel booking' => 'इस विकल्प को सक्षम करने से ग्राहक को पार्सल ट्रैकिंग लिंक एसएमएस के माध्यम से भेजा जाएगा जब वे कोई पार्सल बुकिंग करेंगे',
  'Here you can set the time period during which customers can request a refund for their parcel after completing an order' => 'यहां आप वह समय अवधि निर्धारित कर सकते हैं जिसके दौरान ग्राहक ऑर्डर पूरा करने के बाद अपने पार्सल के लिए धनवापसी का अनुरोध कर सकते हैं',
  'When it’s off the customer will not be able to refund any parcel.' => 'इसके बंद होने पर ग्राहक किसी भी पार्सल को वापस नहीं कर पाएगा।',
  'no_result_found' => 'कोई परिणाम नहीं मिला',
