  'Driver level feature is currently turned off from business settings. If you want to active all the level for drivers in the app, turn on the feature from the settings' => 'ड्राइवर स्तर की सुविधा वर्तमान में व्यावसायिक सेटिंग्स से बंद है। यदि आप ऐप में ड्राइवरों के लिए सभी स्तरों को सक्रिय करना चाहते हैं, तो सेटिंग्स से सुविधा चालू करें',
  'Customer level feature is currently turned off from business settings. If you want to active all the level for customers in the app, turn on the feature from the settings' => 'ग्राहक स्तर की सुविधा वर्तमान में व्यावसायिक सेटिंग्स से बंद है। यदि आप ऐप में ग्राहकों के लिए सभी स्तर को सक्रिय करना चाहते हैं, तो सेटिंग्स से सुविधा को चालू करें',
  'Okay, Got It' => 'ठीक है, समझ गया',
  'search_here_by_id,name,zone' => 'यहां आईडी, नाम, क्षेत्र के आधार पर खोजें',
