  'out_for_pickup' => 'पिकअप के लिए बाहर',
  'File Format - .jpg, .jpeg, .png, .webp. Image Size - Maximum Size 5 MB. Image Ratio - 3:1' => 'फ़ाइल प्रारूप - .jpg, .jpeg, .png, .webp। छवि का आकार - अधिकतम आकार 5 एमबी। छवि अनुपात - 3:1',
  'Clear All' => 'सभी साफ़ करें',
  'If want to Update, Go to the Zone Settings' => 'अगर अपडेट करना चाहते हैं तो जोन सेटिंग्स में जाएं',
  'JPG, JPEG, PNG,Gif Image size : Max 2 MB' => 'जेपीजी, जेपीईजी, पीएनजी, जीआईएफ छवि का आकार: अधिकतम 2 एमबी',
  'If you deactivate this level, all driver under this level will not be able to see the level details in their profile.' => 'यदि आप इस स्तर को निष्क्रिय करते हैं, तो इस स्तर के अंतर्गत आने वाले सभी ड्राइवर अपनी प्रोफ़ाइल में स्तर का विवरण नहीं देख पाएंगे।',
  'Sorry you can t delete this driver, because there are ongoing rides or payment due this driver. ' => 'क्षमा करें, आप इस ड्राइवर को हटा नहीं सकते, क्योंकि इस ड्राइवर पर यात्राएँ या भुगतान देय हैं। ',
  'If you deactivate this level, all customer under this level will not be able to see the level details in their profile.' => 'यदि आप इस स्तर को निष्क्रिय करते हैं, तो इस स्तर के अंतर्गत आने वाले सभी ग्राहक अपनी प्रोफ़ाइल में स्तर का विवरण नहीं देख पाएंगे।',
  'Sorry you can t delete this customer, because there are ongoing rides or payment due this customer. ' => 'क्षमा करें, आप इस ग्राहक को नहीं हटा सकते, क्योंकि इस ग्राहक को यात्राएं या भुगतान देय हैं। ',
  'When toggle is ON, the fare is set by category  when OFF, it s the same for all.' => 'जब टॉगल चालू होता है, तो बंद होने पर किराया श्रेणी के अनुसार निर्धारित होता है, यह सभी के लिए समान होता है।',
  'GIF, Jason Less Than 1MB' => 'जीआईएफ, जेसन 1एमबी से कम',
  'If it is enabled, the driver must verify their identity based on periodic time setup. Setup will appear when you select this option' => 'यदि यह सक्षम है, तो ड्राइवर को आवधिक समय सेटअप के आधार पर अपनी पहचान सत्यापित करनी होगी। जब आप यह विकल्प चुनेंगे तो सेटअप दिखाई देगा',
  'if_you_want_to_charge_more_for_scheduled_trips_than_regular_trips,_turn_on_the_switch.' => 'यदि आप नियमित यात्राओं की तुलना में निर्धारित यात्राओं के लिए अधिक शुल्क लेना चाहते हैं, तो स्विच चालू करें।',
  'if_the_user_fails_to_get_the_OTP_within_a_certain_time,_user_can_request_a_resend' => 'यदि उपयोगकर्ता एक निश्चित समय के भीतर ओटीपी प्राप्त करने में विफल रहता है, तो उपयोगकर्ता पुनः भेजने का अनुरोध कर सकता है',
  'If the toggle is turned ON, Customer will notify if their requested weight exceeds the capacity.' => 'यदि टॉगल चालू है, तो ग्राहक को सूचित किया जाएगा यदि उनका अनुरोधित वजन क्षमता से अधिक है।',
  'Set the value of the day, after that day is over can’t get the referral discount.' => 'दिन का मूल्य निर्धारित करें, उस दिन के समाप्त होने के बाद रेफरल छूट नहीं मिल सकती।',
  'If the toggle is turned ON, customers or drivers will see a list of reasons when sending a safety alert.' => 'यदि टॉगल चालू है, तो ग्राहकों या ड्राइवरों को सुरक्षा चेतावनी भेजते समय कारणों की एक सूची दिखाई देगी।',
  ', the support section will no longer see this Topic & Answer.' => ', सहायता अनुभाग अब इस विषय और उत्तर को नहीं देख पाएगा।',
  'If toggle ON, after complete a trip within a certain time Customer and Drive can use safety feature' => 'यदि टॉगल चालू है, तो एक निश्चित समय के भीतर यात्रा पूरी करने के बाद ग्राहक और ड्राइव सुरक्षा सुविधा का उपयोग कर सकते हैं',
  'Note: Please make sure to use the obtained information securely and in accordance with Firebase and FCM documentation, terms of service, and any applicable laws and regulations.' => 'ध्यान दें: कृपया प्राप्त जानकारी का उपयोग सुरक्षित रूप से और फायरबेस और एफसीएम दस्तावेज़ीकरण, सेवा की शर्तों और किसी भी लागू कानून और विनियमों के अनुसार करना सुनिश्चित करें।',
  'JPG, JPEG, PNG, WEBP Less Than 1MB' => 'JPG, JPEG, PNG, WEBP 1MB से कम',
  'The value of Customer payment successful must contain the placeholders: {paidAmount}, {methodName}.' => 'सफल ग्राहक भुगतान के मूल्य में प्लेसहोल्डर शामिल होने चाहिए: :paidAmount, :methodName।',
  'JPG, JPEG, PNG, WEBP. Less Than 1MB' => 'जेपीजी, जेपीईजी, पीएनजी, वेबपी। 1एमबी से कम',
  'Set minimum iOS app version. If user don t have, they ll be requested a force update.' => 'न्यूनतम iOS ऐप संस्करण सेट करें। यदि उपयोगकर्ता के पास नहीं है, तो उनसे बलपूर्वक अद्यतन का अनुरोध किया जाएगा।',
  'The name has already been taken.' => 'नाम तो लिया ही जा चुका है.',
