  'When Allow Extra Fare Setup - All Zone, the Extra Fare(%) will be applicable for all the active zones.' => 'जब अतिरिक्त किराया सेटअप की अनुमति दी जाती है - सभी जोन, तो अतिरिक्त किराया (%) सभी सक्रिय क्षेत्रों के लिए लागू होगा।',
