  'If you turning off customer level feature, please do it at the beginning stage of business. Because once driver use this feature & you will off this feature they will be confused or worried about it.' => 'यदि आप ग्राहक स्तर की सुविधा बंद कर रहे हैं, तो कृपया इसे व्यवसाय के शुरुआती चरण में करें। क्योंकि एक बार जब ड्राइवर इस सुविधा का उपयोग करेंगे और आप इस सुविधा को बंद कर देंगे तो वे इसके बारे में भ्रमित या चिंतित होंगे।',
  'If you turn ON level feature, customer will see this feature on app.' => 'यदि आप लेवल सुविधा चालू करते हैं, तो ग्राहक को यह सुविधा ऐप पर दिखाई देगी।',
