  'This will be permanently removed from the list.' => 'इसे सूची से स्थायी रूप से हटा दिया जाएगा.',
  'Overlapping with - #' => 'ओवरलैपिंग - #',
  'set_the_maximum_discount_limit_for_this_coupon,_and_the_discount_amount_will_not_increase_after_reaching_this_limit' => 'इस कूपन के लिए अधिकतम छूट सीमा निर्धारित करें, और इस सीमा तक पहुंचने के बाद छूट राशि में वृद्धि नहीं होगी',
  'Are you sure to delete this Surge Price' => 'क्या आप निश्चित रूप से इस सर्ज प्राइस को हटाना चाहते हैं',
  'Select the dates for this surge pricing to be active.' => 'इस सर्ज प्राइसिंग के सक्रिय होने की तारीखें चुनें।',
  'Select the start and end time for this surge pricing to be active.' => 'इस सर्ज प्राइसिंग को सक्रिय करने के लिए प्रारंभ और समाप्ति समय का चयन करें।',
  'Select the days for this surge pricing to be active.' => 'इस सर्ज प्राइसिंग के सक्रिय होने के दिनों का चयन करें।',
  'this_surge_price_will_be_applied_for_:count' => 'यह वृद्धि मूल्य :गिनती के लिए लागू किया जाएगा',
  'When it is on the customer needs to pay extra fare.' => 'इसके चालू होने पर ग्राहक को अतिरिक्त किराया देना पड़ता है।',
  'Select the start and end dates for this surge pricing to be active.' => 'इस सर्ज प्राइसिंग को सक्रिय करने के लिए आरंभ और समाप्ति तिथियों का चयन करें।',
  'Custom – Pick exact dates and times' => 'Custom – Pick exact dates and times',
  'Weekly – Set specific days of the week' => 'Weekly – Set specific days of the week',
  'Do you want to turn On Surge Price' => 'क्या आप सर्ज प्राइस चालू करना चाहते हैं?',
  'this_surge_price_will_be_applied_for_:count_time.' => 'यह वृद्धि मूल्य :गिनती समय के लिए लागू किया जाएगा।',
  'this_surge_price_will_be_applied_for_:count_times.' => 'यह वृद्धि मूल्य :गिनती समय के लिए लागू किया जाएगा।',
  'search_here_by_id, name' => 'यहां आईडी, नाम से खोजें',
  'this_surge_price_will_be_applied_for_:count.' => 'यह वृद्धि मूल्य :गिनती के लिए लागू किया जाएगा।',
  'Daily – Repeats every day during the selected time range' => 'Daily – Repeats every day during the selected time range',
  'Set the surge rate (%) to increase the parcel delivery fee.' => 'पार्सल डिलीवरी शुल्क बढ़ाने के लिए सर्ज रेट (%) निर्धारित करें।',
  'Scooti Rate' => 'स्कूटी रेट',
  'Set surge rate (%) to increase ride fare. Different rates can be set per vehicle type.' => 'सवारी किराया बढ़ाने के लिए सर्ज रेट (%) निर्धारित करें। प्रत्येक वाहन प्रकार के लिए अलग-अलग दरें निर्धारित की जा सकती हैं।',
  'Choose whether to apply surge pricing to Rides, Parcels, or Both.' => 'चुनें कि सवारी, पार्सल या दोनों पर सर्ज प्राइसिंग लागू करना है या नहीं।',
  'Select the zones where this surge price will apply. You can choose one or multiple zones' => 'उन क्षेत्रों का चयन करें जहां यह वृद्धि मूल्य लागू होगा। आप एक या एकाधिक क्षेत्र चुन सकते हैं',
  'this_surge_price_will_be_applied_for_0_time.' => 'यह सर्ज प्राइस 0 बार के लिए लागू किया जाएगा।',
  'Customers see the surge fee before confirming, and drivers receive higher earnings for those trips.' => 'ग्राहक पुष्टि करने से पहले सर्ज शुल्क देखते हैं, और ड्राइवरों को उन यात्राओं के लिए उच्च आय प्राप्त होती है।',
  'When active, the surge fee is automatically added to the normal fare for rides or parcel deliveries.' => 'सक्रिय होने पर, सर्ज शुल्क स्वचालित रूप से सवारी या पार्सल डिलीवरी के सामान्य किराए में जुड़ जाता है।',
  'The admin manually creates a surge price rule for specific zones, vehicle types, or time periods.' => 'व्यवस्थापक विशिष्ट क्षेत्रों, वाहन प्रकारों या समयावधियों के लिए मैन्युअल रूप से वृद्धि मूल्य नियम बनाता है।',
  'How Surge Price Work' => 'बढ़ती कीमत कैसे काम करती है',
  'this_surge_price_will_be_applied_for_{count}.' => 'यह वृद्धि मूल्य :count के लिए लागू किया जाएगा।',
  'Days Selected' => 'चयनित दिन',
  'every_week_from_{startDate}_to_{endDate}' => 'प्रत्येक सप्ताह :startDate से :endDate तक',
  'every_week_from_:startDate_to_:endDate' => 'हर सप्ताह :startDate से :endDate तक',
  'To ensure customers can still get rides or deliveries when conditions are less favorable.' => 'यह सुनिश्चित करने के लिए कि परिस्थितियाँ कम अनुकूल होने पर भी ग्राहकों को सवारी या डिलीवरी मिल सके।',
  'Total {countDays} Days Applied' => 'कुल :countDays लागू दिन',
  'This charge is added to a ride for special conditions, such as extreme weather.' => 'यह शुल्क अत्यधिक मौसम जैसी विशेष परिस्थितियों के लिए सवारी में जोड़ा जाता है।',
  'If you close now, the progress made so far will be saved. The remaining content will not be translated.' => 'यदि आप अभी बंद करते हैं, तो अब तक की गई प्रगति बच जाएगी। शेष सामग्री का अनुवाद नहीं किया जाएगा.',
  'Translating_may_take_up_to_{time}' => 'अनुवाद करने में :time तक का समय लग सकता है',
  'few hours' => 'कुछ घंटे',
  'To fairly compensate drivers for the extra time and effort needed in tough situations.' => 'कठिन परिस्थितियों में आवश्यक अतिरिक्त समय और प्रयास के लिए ड्राइवरों को उचित मुआवजा देना।',
  'Scootiasdfa Rate' => 'स्कूटियासडफ़ा दर',
  'Why Surge Price is Needed' => 'सर्ज प्राइस की आवश्यकता क्यों है?',
  'for example, during heavy rain, traffic jams, or other challenging conditions.' => 'उदाहरण के लिए, भारी बारिश, ट्रैफिक जाम या अन्य चुनौतीपूर्ण परिस्थितियों के दौरान।',
  'Surge Price is an extra fee added to rides or parcel deliveries during high-demand or difficult times when completing a trip requires more effort from drivers' => 'सर्ज प्राइस एक अतिरिक्त शुल्क है जो उच्च मांग या कठिन समय के दौरान सवारी या पार्सल डिलीवरी पर जोड़ा जाता है जब यात्रा पूरी करने के लिए ड्राइवरों को अधिक प्रयास की आवश्यकता होती है',
  'What is Surge Price' => 'सर्ज प्राइस क्या है',
  'No,_Continue' => 'नहीं, जारी रखें',
  'Yes,_Close' => 'हाँ, बंद करें',
  'Translating_in_progress._Are_you_sure,_want_to_close_this_tab _If_you_close_the_tab,_the_progress_made_will_be_saved_but_remaining_content_will_not_be_translated..' => 'अनुवाद प्रगति पर है. क्या आप निश्चित हैं, इस टैब को बंद करना चाहते हैं यदि आप टैब बंद करते हैं, तो की गई प्रगति सहेज ली जाएगी लेकिन शेष सामग्री का अनुवाद नहीं किया जाएगा।',
  'Yes,_Translate_All' => 'हाँ, सभी का अनुवाद करें',
  'Fund Setup' => 'फंड सेटअप',
  'Add_fund' => 'फंड जोड़ें',
  'Wallet_bonus' => 'वॉलेट बोनस',
  'if_enabled,_drivers_can_register_themselves_from_the_driver_app' => 'सक्षम होने पर, ड्राइवर ड्राइवर ऐप से स्वयं को पंजीकृत कर सकते हैं',
  'Set the maximum number of parcels delivery a driver can carry at once. Once the limit is reached, the driver cannot accept new parcel requests until existing deliveries are completed.' => 'एक ड्राइवर द्वारा एक बार में पार्सल डिलीवरी की अधिकतम संख्या निर्धारित करें। एक बार सीमा पूरी हो जाने पर, मौजूदा डिलीवरी पूरी होने तक ड्राइवर नए पार्सल अनुरोध स्वीकार नहीं कर सकता।',
  'Enable this, customers will gain access to level-specific features and benefits' => 'इसे सक्षम करें, ग्राहकों को स्तर-विशिष्ट सुविधाओं और लाभों तक पहुंच प्राप्त होगी',
  'If a driver updates the details of an existing vehicle, certain changes may require admin approval.' => 'यदि कोई ड्राइवर मौजूदा वाहन का विवरण अपडेट करता है, तो कुछ बदलावों के लिए प्रशासन की मंजूरी की आवश्यकता हो सकती है।',
  'Ex: 100' => 'उदाहरण: 100',
  'Bonus_List' => 'बोनस सूची',
  'Driver Cash in Hand Setup' => 'ड्राइवर कैश इन हैंड सेटअप',
  'Manage the Cash in Hand balance of Deliveryman from here' => 'यहां से डिलीवरीमैन के कैश इन हैंड बैलेंस को प्रबंधित करें',
  'SUBMIT' => 'सबमिट करें',
  'add_nesdfdsfw_model' => 'nesdfdsfw मॉडल जोड़ें',
  'add_New_Vsdfdsfehicle' => 'नया Vsdfdsfehicle जोड़ें',
  'edit_vehisdfdscle' => 'vehisdfdscle संपादित करें',
  'available_vehicsdfdsfles_in_this_zone' => 'इस क्षेत्र में वाहन उपलब्ध हैं',
  'business_managsdfdsfement' => 'बिजनेस मैनेज्सडीएफडीएसफेमेंट',
  'If Yes, customers can add routes between pickup and destination' => 'यदि हां, तो ग्राहक पिकअप और गंतव्य के बीच मार्ग जोड़ सकते हैं',
  'When the time is over, the requests get removed automatically.' => 'समय समाप्त होने पर अनुरोध स्वचालित रूप से हटा दिए जाते हैं।',
  'When this option is enabled, for starting the trip, the driver will need to get an OTP from the customer' => 'जब यह विकल्प सक्षम हो जाएगा तो यात्रा शुरू करने के लिए ड्राइवर को ग्राहक से एक ओटीपी प्राप्त करना होगा',
  'Do you want to turn ON Parcel Return Time & Fee for driver  When it’s ON, the driver need to pay parcel return delay fee. ' => 'क्या आप ड्राइवर के लिए पार्सल वापसी का समय और शुल्क चालू करना चाहते हैं, जब यह चालू होता है, तो ड्राइवर को पार्सल वापसी विलंब शुल्क का भुगतान करना होगा। ',
  'this_time_is_the_minimum_advance_booking_time_for_scheduled_trips,_customer_cant_book_a_scheduled_trip_before_this.' => 'यह समय निर्धारित यात्राओं के लिए न्यूनतम अग्रिम बुकिंग का समय है, ग्राहक इससे पहले निर्धारित यात्रा बुक नहीं कर सकता।',
  'this_time_is_the_maximum_advance_booking_time_for_scheduled_trips,_customer_can_not_book_a_scheduled_trip_if_the_time_is_over.' => 'यह समय निर्धारित यात्राओं के लिए अधिकतम अग्रिम बुकिंग का समय है, यदि समय समाप्त हो गया है तो ग्राहक निर्धारित यात्रा बुक नहीं कर सकता है।',
  'By default, it is set to 5 kilometers' => 'डिफ़ॉल्ट रूप से, यह 5 किलोमीटर पर सेट है',
  'By default, it is set to 10 meters' => 'डिफ़ॉल्ट रूप से, यह 10 मीटर पर सेट है',
  'Socket connection establishing URL is base url, Its is not editable' => 'सॉकेट कनेक्शन स्थापित करने वाला यूआरएल आधार यूआरएल है, यह संपादन योग्य नहीं है',
  'Do you want to turn ON Parcel Tracking Link for customer  When turned ON, customers will receive a tracking link once the parcel is confirmed.' => 'क्या आप ग्राहक के लिए पार्सल ट्रैकिंग लिंक चालू करना चाहते हैं, चालू होने पर, पार्सल की पुष्टि होने पर ग्राहकों को एक ट्रैकिंग लिंक प्राप्त होगा।',
  'Hear you can write a massage body. Customer Name, Parcel ID & Tracking link will generate automatically for each individual parcel.' => 'सुना है आप मसाज बॉडी लिख सकते हैं। प्रत्येक व्यक्तिगत पार्सल के लिए ग्राहक का नाम, पार्सल आईडी और ट्रैकिंग लिंक स्वचालित रूप से उत्पन्न होगा।',
  'When the toggle is turned ON, the parcel return time and fee are activated  when turned OFF, they are deactivated.' => 'जब टॉगल चालू होता है, तो पार्सल वापसी का समय और शुल्क सक्रिय हो जाता है, बंद होने पर वे निष्क्रिय हो जाते हैं।',
  'If turned ON, customer will notify if their requested weight exceeds the capacity.' => 'चालू होने पर, यदि उनका अनुरोधित वजन क्षमता से अधिक है तो ग्राहक सूचित करेंगे।',
  'If the toggle is turned OFF, Customer will not notify if their requested weight exceeds the capacity.' => 'यदि टॉगल बंद कर दिया जाता है, तो ग्राहक को सूचित नहीं किया जाएगा कि उनका अनुरोधित वजन क्षमता से अधिक है या नहीं।',
  'Image format : jpg, png, jpeg, webp | Maximum size : 5MB' => 'छवि प्रारूप: जेपीजी, पीएनजी, जेपीईजी, वेबपी | अधिकतम आकार : 5एमबी',
  'Navigate Life with Ease: Welcome to DriveMond, Your Premier Ride-Sharing Experience!' => 'जीवन को आसानी से नेविगेट करें: ड्राइवमोंड में आपका स्वागत है, आपका प्रमुख राइड-शेयरिंग अनुभव!',
  'Unlock a World of Convenience: Welcome to DriveMond, Your Ultimate Ride-Sharing Destination! Seamlessly Connect with Reliable Drivers, Enjoy Comfortable Journeys- One Ride at a Time.' => 'सुविधा की दुनिया को अनलॉक करें: ड्राइवमंड में आपका स्वागत है, आपका अंतिम राइड-शेयरिंग गंतव्य! विश्वसनीय ड्राइवरों के साथ निर्बाध रूप से जुड़ें, आरामदायक यात्राओं का आनंद लें- एक समय में एक सवारी।',
  ' Experience the pinnacle of convenience with our ride service—prompt pickups, smooth journeys, and satisfaction guaranteed, all in one ride. ' => ' Experience the pinnacle of convenience with our ride service—prompt pickups, smooth journeys, and satisfaction guaranteed, all in one ride. ',
  ' Join our community of happy customers! Discover seamless experiences, personalized service, and satisfaction guaranteed. Your joy is our priority! ' => ' खुश ग्राहकों के हमारे समुदाय में शामिल हों! निर्बाध अनुभव, वैयक्तिकृत सेवा और गारंटीकृत संतुष्टि की खोज करें। आपकी खुशी हमारी प्राथमिकता है! ',
  'Set minimum Android app version. If user don t have, they ll be requested a force update.' => 'न्यूनतम एंड्रॉइड ऐप संस्करण सेट करें। यदि उपयोगकर्ता के पास नहीं है, तो उनसे बलपूर्वक अद्यतन का अनुरोध किया जाएगा।',
  'File Format - jpg, jpeg, png, webp | Image Size - Maximum Size 5 MB.' => 'फ़ाइल प्रारूप - जेपीजी, जेपीईजी, पीएनजी, वेबपी | छवि का आकार - अधिकतम आकार 5 एमबी।',
  'With Firebase OTP enabled, verification codes will be sent through Firebase.' => 'फायरबेस ओटीपी सक्षम होने पर, सत्यापन कोड फायरबेस के माध्यम से भेजे जाएंगे।',
  'If you disable Firebase OTP, users will no longer receive verification codes via Firebase. You must activate Email or SMS verification as an alternative' => 'यदि आप फायरबेस ओटीपी को अक्षम करते हैं, तो उपयोगकर्ताओं को फायरबेस के माध्यम से सत्यापन कोड प्राप्त नहीं होंगे। आपको विकल्प के रूप में ईमेल या एसएमएस सत्यापन सक्रिय करना होगा',
  'For configuring OTP in the Firebase, you must create a Firebase project first. If you haven’t created any project for your application yet, please create a project first.' => 'फायरबेस में ओटीपी कॉन्फ़िगर करने के लिए, आपको पहले एक फायरबेस प्रोजेक्ट बनाना होगा। यदि आपने अभी तक अपने एप्लिकेशन के लिए कोई प्रोजेक्ट नहीं बनाया है, तो कृपया पहले एक प्रोजेक्ट बनाएं।',
  'From the Sign-in providers section, select the Phone option.' => 'साइन-इन प्रदाता अनुभाग से, फ़ोन विकल्प चुनें।',
  'If there is any existing user in this level, you can not change the status' => 'यदि इस स्तर पर कोई मौजूदा उपयोगकर्ता है, तो आप स्थिति नहीं बदल सकते',
  'Setting the Stage for Rewards and Targets. Once a target is completed or fulfilled, move on to the next one' => 'पुरस्कारों और लक्ष्यों के लिए मंच तैयार करना। एक बार जब कोई लक्ष्य पूरा हो जाए या पूरा हो जाए, तो अगले लक्ष्य की ओर बढ़ें',
  'When a new customer logs into the app, they start at a default level. This level helps new customers get used to the platform. As the customer completes rides and meets specific performance goals set by the admin, they can move up to the next level.' => 'जब कोई नया ग्राहक ऐप में लॉग इन करता है, तो वे डिफ़ॉल्ट स्तर पर शुरू होते हैं। यह स्तर नए ग्राहकों को प्लेटफ़ॉर्म का आदी होने में मदद करता है। जैसे ही ग्राहक सवारी पूरी करता है और व्यवस्थापक द्वारा निर्धारित विशिष्ट प्रदर्शन लक्ष्यों को पूरा करता है, वे अगले स्तर तक आगे बढ़ सकते हैं।',
  'Using  Add New Level  the admin can create a new level for customers. To set up a new level, the admin needs to define targets and points to be earned. When a customer meets those targets and earns the required points, they will upgrade to the new level from their current one.' => 'ऐड न्यू लेवल का उपयोग करके एडमिन ग्राहकों के लिए एक नया लेवल बना सकता है। एक नया स्तर स्थापित करने के लिए, व्यवस्थापक को अर्जित किए जाने वाले लक्ष्यों और अंकों को परिभाषित करने की आवश्यकता है। जब कोई ग्राहक उन लक्ष्यों को पूरा करता है और आवश्यक अंक अर्जित करता है, तो वे अपने वर्तमान स्तर से नए स्तर पर अपग्रेड हो जाएंगे।',
  'When creating a level, need to prioritize defining the targets before the customer uses this level and points required for a customer to achieve that level. If there is a mismatch in setting these criteria, it may affect the customer s ability to reach the level.' => 'एक स्तर बनाते समय, ग्राहक द्वारा इस स्तर का उपयोग करने से पहले लक्ष्यों को परिभाषित करने को प्राथमिकता देने की आवश्यकता होती है और ग्राहक को उस स्तर को प्राप्त करने के लिए आवश्यक बिंदुओं की आवश्यकता होती है। यदि इन मानदंडों को निर्धारित करने में कोई विसंगति है, तो यह ग्राहक की स्तर तक पहुंचने की क्षमता को प्रभावित कर सकता है।',
  'At present, there is only one level available, which is the default level. When a customer logs in to the app for the first time, they will automatically be assigned the default level.' => 'वर्तमान में, केवल एक ही स्तर उपलब्ध है, जो डिफ़ॉल्ट स्तर है। जब कोई ग्राहक पहली बार ऐप में लॉग इन करता है, तो उन्हें स्वचालित रूप से डिफ़ॉल्ट स्तर निर्दिष्ट किया जाएगा।',
  'At present, there is only one level available, which is the default level. When a driver logs in to the app for the first time, they will automatically be assigned the default level.' => 'वर्तमान में, केवल एक ही स्तर उपलब्ध है, जो डिफ़ॉल्ट स्तर है। जब कोई ड्राइवर पहली बार ऐप में लॉग इन करता है, तो उन्हें स्वचालित रूप से डिफ़ॉल्ट स्तर असाइन किया जाएगा।',
  'Coupon already expired, You do not change this status.' => 'कूपन पहले ही समाप्त हो चुका है, आप इस स्थिति को नहीं बदलेंगे।',
  'Once you turn off this option, Customers will not be required to pay any Extra Fares in this Zone' => 'एक बार जब आप इस विकल्प को बंद कर देते हैं, तो ग्राहकों को इस क्षेत्र में कोई अतिरिक्त किराया नहीं देना होगा',
  'File Format - jpg, png, jpeg, webp' => 'फ़ाइल प्रारूप - जेपीजी, पीएनजी, जेपीईजी, वेबपी',
