  'If checked, customers will no pay a return fee when the deliveryman cancels after pickup' => 'यदि जांच की जाती है, तो डिलीवरीमैन द्वारा पिकअप के बाद रद्द करने पर ग्राहकों को कोई रिटर्न शुल्क नहीं देना होगा',
