  'In the Project settings page, click on the  Cloud Messaging  tab from the top menu.' => 'प्रोजेक्ट सेटिंग पृष्ठ में, शीर्ष मेनू से क्लाउड मैसेजिंग टैब पर क्लिक करें।',
  'In the Firebase Project settings page, click on the  General  tab from the top menu.' => 'फायरबेस प्रोजेक्ट सेटिंग पृष्ठ में, शीर्ष मेनू से सामान्य टैब पर क्लिक करें।',
  'Under the  Your apps  section, click on the  Web  app for which you want to configure FCM.' => 'आपके ऐप्स अनुभाग के अंतर्गत, उस वेब ऐप पर क्लिक करें जिसके लिए आप FCM कॉन्फ़िगर करना चाहते हैं।',
  'Then Obtain API Key, FCM Project ID, Auth Domain, Storage Bucket, Messaging Sender ID.' => 'फिर एपीआई कुंजी, एफसीएम प्रोजेक्ट आईडी, ऑथ डोमेन, स्टोरेज बकेट, मैसेजिंग सेंडर आईडी प्राप्त करें।',
  'parcel_return_penalty' => 'पार्सल वापसी जुर्माना',
