  'customer_refunded_to_wallet' => 'ग्राहक को वॉलेट में पैसा वापस कर दिया गया',
  'The value of Customer refunded to wallet must contain the placeholders: {parcelId}, {approximateAmount}.' => 'वॉलेट में लौटाए गए ग्राहक के मूल्य में प्लेसहोल्डर शामिल होने चाहिए: :parcelId, :approximateAmount।',
  'The value of customer_parcel_canceled must contain the placeholders: {dueTime}.' => 'रद्द किए गए ग्राहक पार्सल के मूल्य में प्लेसहोल्डर शामिल होने चाहिए: :dueTime।',
  'When you turn on the bonus, customer will receive the bonus after add fund to their wallet .' => 'जब आप बोनस चालू करते हैं, तो ग्राहक को अपने वॉलेट में फंड जोड़ने के बाद बोनस प्राप्त होगा।',
  'wallet_Bonus_Setup' => 'वॉलेट बोनस सेटअप',
