  'Manage the Cash in Hand balance of driver from here' => 'यहां से ड्राइवर के कैश इन हैंड बैलेंस को प्रबंधित करें',
  'Minimum_Add_Amount' => 'न्यूनतम जोड़ राशि',
  'Turn Off Cash In Hand Limit' => 'कैश इन हैंड लिमिट बंद करें',
  'If you turn off this feature driver will not have a limit on holding cash' => 'यदि आप इस सुविधा को बंद कर देते हैं तो ड्राइवर के पास नकदी रखने की कोई सीमा नहीं होगी',
  'If you turn off this feature, driver will not have a limit on holding cash' => 'यदि आप इस सुविधा को बंद कर देते हैं, तो ड्राइवर के पास नकदी रखने की कोई सीमा नहीं होगी',
  'If checked, customers will not pay a return fee when the driver cancels after the trip has started.' => 'यदि जाँच की जाती है, तो यात्रा शुरू होने के बाद ड्राइवर द्वारा रद्द करने पर ग्राहकों को वापसी शुल्क नहीं देना होगा।',
