  'allow_drivers_and_customers_to_bid_on_trip_fares.' => 'ड्राइवरों और ग्राहकों को यात्रा किराये पर बोली लगाने की अनुमति दें।',
  'enable_this_option_to_allow_drivers_to_bid_on_ride_fares_instead_of_accepting_fixed_prices.' => 'ड्राइवरों को निर्धारित कीमतों को स्वीकार करने के बजाय सवारी किराए पर बोली लगाने की अनुमति देने के लिए इस विकल्प को सक्षम करें।',
  'Pagination_Setting' => 'पेजिनेशन सेटिंग',
  'define_how_many_items_appear_per_page_in_listings.' => 'परिभाषित करें कि लिस्टिंग में प्रति पृष्ठ कितने आइटम दिखाई देते हैं।',
  'Pagination_Limit' => 'पृष्ठांकन सीमा',
  'set_the_number_of_items_(e.g.,_rides,_users,_drivers)_displayed_per_page_in_the_admin_panel_listings._by_default_it_is_10.' => 'व्यवस्थापक पैनल लिस्टिंग में प्रति पृष्ठ प्रदर्शित वस्तुओं (जैसे, सवारी, उपयोगकर्ता, ड्राइवर) की संख्या निर्धारित करें। डिफ़ॉल्ट रूप से यह 10 है.',
