  'Allow customers to add extra stops during booking.' => 'ग्राहकों को बुकिंग के दौरान अतिरिक्त स्टॉप जोड़ने की अनुमति दें।',
  'Enable extra stops ' => 'अतिरिक्त स्टॉप सक्षम करें ',
  'Trip Request Active Time' => 'यात्रा अनुरोध सक्रिय समय',
  'Set how long the trip request stays visible to drivers before it expires.' => 'सेट करें कि यात्रा अनुरोध समाप्त होने से पहले कितने समय तक ड्राइवरों को दिखाई देता रहे।',
  'Active time (mins)' => 'सक्रिय समय (मिनट)',
  'Require OTP verification for extra security before starting the trip.' => 'यात्रा शुरू करने से पहले अतिरिक्त सुरक्षा के लिए ओटीपी सत्यापन की आवश्यकता है।',
  'OTP confirmation required to start trip.' => 'यात्रा शुरू करने के लिए ओटीपी पुष्टिकरण आवश्यक है।',
