  'Set the minimum time (in minutes or hours) before the ride start time that a customer can schedule a trip.' => 'सवारी शुरू होने के समय से पहले न्यूनतम समय (मिनट या घंटों में) निर्धारित करें जिससे ग्राहक यात्रा निर्धारित कर सके।',
  'Define how far in advance (in days or hours) a customer can book a scheduled ride.' => 'परिभाषित करें कि कोई ग्राहक कितनी पहले (दिनों या घंटों में) निर्धारित सवारी बुक कर सकता है।',
  'Driver Notification' => 'ड्राइवर अधिसूचना',
