  'Set when drivers should be notified about upcoming scheduled trips (e.g., 30 mins before start).' => 'सेट करें कि ड्राइवरों को आगामी निर्धारित यात्राओं के बारे में कब सूचित किया जाना चाहिए (उदाहरण के लिए, शुरू होने से 30 मिनट पहले)।',
  'Fare Increase' => 'किराया वृद्धि',
