  'Enable automatic fare increase for scheduled trips during peak hours or high-demand times.' => 'व्यस्त घंटों या उच्च मांग वाले समय के दौरान निर्धारित यात्राओं के लिए स्वचालित किराया वृद्धि सक्षम करें।',
  'Specify the percentage increase in fare for scheduled trips when demand or time-based pricing applies.' => 'मांग या समय-आधारित मूल्य निर्धारण लागू होने पर निर्धारित यात्राओं के लिए किराए में प्रतिशत वृद्धि निर्दिष्ट करें।',
  'Add or manage preset cancellation reasons that users or drivers can select when cancelling a trip.' => 'पूर्वनिर्धारित रद्दीकरण कारण जोड़ें या प्रबंधित करें जिन्हें उपयोगकर्ता या ड्राइवर यात्रा रद्द करते समय चुन सकते हैं।',
  'set_trip_fares_and_penalties_for_delays_or_idle_time.' => 'देरी या निष्क्रिय समय के लिए यात्रा किराया और जुर्माना निर्धारित करें।',
  'Idle_fee ' => 'निष्क्रिय शुल्क ',
