  'set_time_(in_minutes)_after_which_the_system_starts_calculating_idle_waiting_charges_during_a_trip.' => 'समय निर्धारित करें (मिनटों में) जिसके बाद सिस्टम यात्रा के दौरान निष्क्रिय प्रतीक्षा शुल्क की गणना शुरू कर देता है।',
  'set_time_(in_minutes)_after_which_delay_fees_begin_to_apply_if_the_trip_exceeds_the_estimated_duration.' => 'समय निर्धारित करें (मिनटों में) जिसके बाद यदि यात्रा अनुमानित अवधि से अधिक हो जाती है तो विलंब शुल्क लागू होना शुरू हो जाता है।',
  'the fee charged when a driver waits without a trip.' => 'जब कोई ड्राइवर बिना यात्रा के प्रतीक्षा करता है तो शुल्क लिया जाता है।',
  'The fee applied when a trip is delayed beyond the set time.' => 'यह शुल्क तब लागू होता है जब किसी यात्रा में निर्धारित समय से अधिक देरी हो जाती है।',
