  'If you disable scheduled trips, then users will no longer be able to book rides in advance.' => 'यदि आप निर्धारित यात्राओं को अक्षम कर देते हैं, तो उपयोगकर्ता पहले से सवारी बुक नहीं कर पाएंगे।',
  'Want to enable scheduled trips' => 'निर्धारित यात्राएँ सक्षम करना चाहते हैं',
  'If you enable scheduled trips, then users will be able to book rides in advance.' => 'यदि आप निर्धारित यात्राएँ सक्षम करते हैं, तो उपयोगकर्ता पहले से सवारी बुक कर सकेंगे।',
  'Want to disable referral earnings' => 'रेफरल आय को अक्षम करना चाहते हैं',
  'If you disable referral earnings, customers will no longer receive rewards for referring new users' => 'यदि आप रेफरल आय को अक्षम कर देते हैं, तो ग्राहकों को नए उपयोगकर्ताओं को रेफर करने के लिए पुरस्कार नहीं मिलेंगे',
  'Want to enable referral earnings' => 'रेफरल आय सक्षम करना चाहते हैं',
  'If you enable referral earnings, customers will be able to earn rewards by referring new users.' => 'यदि आप रेफरल आय सक्षम करते हैं, तो ग्राहक नए उपयोगकर्ताओं को रेफर करके पुरस्कार अर्जित करने में सक्षम होंगे।',
  'If you disable referral earnings, drivers will no longer receive rewards for referring new users' => 'यदि आप रेफरल आय को अक्षम कर देते हैं, तो ड्राइवरों को नए उपयोगकर्ताओं को रेफर करने के लिए पुरस्कार नहीं मिलेगा',
  'If you enable referral earnings, drivers will be able to earn rewards by referring new users.' => 'यदि आप रेफरल आय सक्षम करते हैं, तो ड्राइवर नए उपयोगकर्ताओं को रेफर करके पुरस्कार अर्जित करने में सक्षम होंगे।',
  'The idle fee is applied when the driver pauses an ongoing trip.' => 'निष्क्रिय शुल्क तब लागू होता है जब ड्राइवर चल रही यात्रा को रोक देता है।',
  'Set the default currency used across your platform for pricing and transactions.' => 'मूल्य निर्धारण और लेनदेन के लिए अपने प्लेटफ़ॉर्म पर उपयोग की जाने वाली डिफ़ॉल्ट मुद्रा सेट करें।',
  'Want to enable driver self-registration' => 'ड्राइवर स्व-पंजीकरण सक्षम करना चाहते हैं',
  ' If you turn on the driver self-registration, drivers can register directly. This streamlines onboarding.' => ' यदि आप ड्राइवर स्व-पंजीकरण चालू करते हैं, तो ड्राइवर सीधे पंजीकरण कर सकते हैं। यह ऑनबोर्डिंग को सुव्यवस्थित करता है।',
  'If you turn on the driver verification, drivers must pass the verification process before they can start taking trips.' => 'यदि आप ड्राइवर सत्यापन चालू करते हैं, तो यात्रा शुरू करने से पहले ड्राइवरों को सत्यापन प्रक्रिया से गुजरना होगा।',
  'Want to disable driver self-registration' => 'ड्राइवर स्व-पंजीकरण अक्षम करना चाहते हैं',
  'If you turn off the driver self-registration, drivers will require an internal administrator to register their accounts.' => 'यदि आप ड्राइवर स्व-पंजीकरण बंद कर देते हैं, तो ड्राइवरों को अपने खाते पंजीकृत करने के लिए एक आंतरिक व्यवस्थापक की आवश्यकता होगी।',
  'Want to enable driver verification' => 'ड्राइवर सत्यापन सक्षम करना चाहते हैं',
  'Want to disable driver verification' => 'ड्राइवर सत्यापन अक्षम करना चाहते हैं',
  'If you turn off the driver verification, drivers will operate without identity checks, which severely compromises platform safety and compliance.' => 'यदि आप ड्राइवर सत्यापन बंद कर देते हैं, तो ड्राइवर पहचान जांच के बिना काम करेंगे, जो प्लेटफ़ॉर्म सुरक्षा और अनुपालन से गंभीर रूप से समझौता करता है।',
  'Want to enable customer verification' => 'ग्राहक सत्यापन सक्षम करना चाहते हैं',
  ' If you turn on the customer verification, Customers will verify their identity to use restricted features.' => ' यदि आप ग्राहक सत्यापन चालू करते हैं, तो ग्राहक प्रतिबंधित सुविधाओं का उपयोग करने के लिए अपनी पहचान सत्यापित करेंगे।',
