  'Verification status is updated as Verified, Failed, or Skipped based on the result.' => 'परिणाम के आधार पर सत्यापन स्थिति को सत्यापित, विफल या छोड़ दिया गया के रूप में अद्यतन किया जाता है।',
  'The system captures a live facial image and verifies it against the driver’s stored profile photo.' => 'सिस्टम एक लाइव चेहरे की छवि कैप्चर करता है और इसे ड्राइवर की संग्रहीत प्रोफ़ाइल फ़ोटो के विरुद्ध सत्यापित करता है।',
