  'Drivers are prompted to complete face verification during signup or at defined verification checkpoints.' => 'ड्राइवरों को साइनअप के दौरान या परिभाषित सत्यापन चौकियों पर चेहरे का सत्यापन पूरा करने के लिए कहा जाता है।',
