  'Drivers will see the identity verification option when switching from offline to online.' => 'ऑफ़लाइन से ऑनलाइन पर स्विच करने पर ड्राइवरों को पहचान सत्यापन विकल्प दिखाई देगा।',
  'Trigger when switching to online' => 'ऑनलाइन पर स्विच करते समय ट्रिगर',
  'This helps ensure driver identity, authenticity, and platform safety before allowing full access or promotions.' => 'यह पूर्ण पहुंच या प्रचार की अनुमति देने से पहले ड्राइवर की पहचान, प्रामाणिकता और प्लेटफ़ॉर्म सुरक्षा सुनिश्चित करने में मदद करता है।',
  'Purpose' => 'प्रयोजन',
  'Admins can view driver details and decide when to prompt or require re-verification.' => 'व्यवस्थापक ड्राइवर विवरण देख सकते हैं और निर्णय ले सकते हैं कि कब संकेत देना है या पुन: सत्यापन की आवश्यकता है।',
  'Admin Review' => 'व्यवस्थापक समीक्षा',
  'The system records how many verification attempts were made and the last attempt time.' => 'सिस्टम रिकॉर्ड करता है कि कितने सत्यापन प्रयास किए गए और अंतिम प्रयास का समय।',
  'Attempts Tracking' => 'ट्रैकिंग का प्रयास',
  'Drivers who attempt verification but fail will be marked as Failed, along with the number of attempts made.' => 'जो ड्राइवर सत्यापन का प्रयास करते हैं लेकिन असफल होते हैं उन्हें किए गए प्रयासों की संख्या के साथ विफल के रूप में चिह्नित किया जाएगा।',
  'face_verification' => 'चेहरा सत्यापन',
  'face_verification_completed_successfully' => 'चेहरे का सत्यापन सफलतापूर्वक पूरा हुआ',
  'face_verification_failed' => 'चेहरे का सत्यापन विफल',
  'Send notification to drivers about verification status' => 'सत्यापन स्थिति के बारे में ड्राइवरों को अधिसूचना भेजें',
  'Pick the date that you want to show for the customer as the blog publishing date.' => 'वह दिनांक चुनें जिसे आप ग्राहक के लिए ब्लॉग प्रकाशन दिनांक के रूप में दिखाना चाहते हैं।',
  'If no categories are available or want to add new category please add it from the manage category section' => 'यदि कोई श्रेणियां उपलब्ध नहीं हैं या नई श्रेणी जोड़ना चाहते हैं तो कृपया इसे प्रबंधन श्रेणी अनुभाग से जोड़ें',
  'The registered name of the business or application' => 'व्यवसाय या एप्लिकेशन का पंजीकृत नाम',
  'Select a category from the dropdown menu to assign this blog.' => 'इस ब्लॉग को निर्दिष्ट करने के लिए ड्रॉपडाउन मेनू से एक श्रेणी चुनें।',
  'Complete the setup of the app store download buttons you want to display to users.' => 'ऐप स्टोर डाउनलोड बटन का सेटअप पूरा करें जिसे आप उपयोगकर्ताओं को दिखाना चाहते हैं।',
  'When you turn off this category, It can not be accessed and visible for selection' => 'जब आप इस श्रेणी को बंद कर देते हैं, तो इसे चयन के लिए एक्सेस और दृश्यमान नहीं किया जा सकता है',
  'Our ' => 'हमारा ',
  'See how your our services Section will look to customers.' => 'देखें कि आपका हमारा सेवा अनुभाग ग्राहकों को कैसा दिखेगा।',
  'Configure the tab content by setting the tab name, title, subtitle, and background image.' => 'टैब नाम, शीर्षक, उपशीर्षक और पृष्ठभूमि छवि सेट करके टैब सामग्री कॉन्फ़िगर करें।',
  'Upload our services Section Image' => 'हमारी सेवाएँ अनुभाग छवि अपलोड करें',
  'Configure the setup, view the section preview, and check the notes for setup guidance.' => 'सेटअप कॉन्फ़िगर करें, अनुभाग पूर्वावलोकन देखें, और सेटअप मार्गदर्शन के लिए नोट्स की जाँच करें।',
  'Footer_Section_Content' => 'पाद लेख अनुभाग सामग्री',
  'Set up the section by adding a title and configuring the customer app and driver app from the required sections.' => 'एक शीर्षक जोड़कर और आवश्यक अनुभागों से ग्राहक ऐप और ड्राइवर ऐप को कॉन्फ़िगर करके अनुभाग सेट करें।',
  'Allow this option to display the Newsletter Section on the landing page.' => 'इस विकल्प को लैंडिंग पृष्ठ पर न्यूज़लेटर अनुभाग प्रदर्शित करने की अनुमति दें।',
  'Configure the section content by setting the title, subtitle, and background image.' => 'शीर्षक, उपशीर्षक और पृष्ठभूमि छवि सेट करके अनुभाग सामग्री को कॉन्फ़िगर करें।',
  'Are you sure to turn off this solution' => 'क्या आप निश्चित रूप से इस समाधान को बंद कर देंगे?',
  'Once you turn off this solution' => 'एक बार आप इस घोल को बंद कर दें',
  ', the landing page will no longer have this solution.' => ', लैंडिंग पृष्ठ पर अब यह समाधान नहीं होगा।',
  'Are you sure to delete this Solution' => 'क्या आप निश्चित रूप से इस समाधान को हटा देंगे?',
  'Allow the option to display the Gallery on the landing page.' => 'लैंडिंग पृष्ठ पर गैलरी प्रदर्शित करने के विकल्प को अनुमति दें।',
  'Allow this option to display the app download section on the landing page.' => 'इस विकल्प को लैंडिंग पृष्ठ पर ऐप डाउनलोड अनुभाग प्रदर्शित करने की अनुमति दें।',
  'Configure the section content by setting the title, subtitle, and image.' => 'शीर्षक, उपशीर्षक और छवि सेट करके अनुभाग सामग्री को कॉन्फ़िगर करें।',
  'Set a title and subtitle that will appear on the landing page to inform about customer app downloads.' => 'एक शीर्षक और उपशीर्षक सेट करें जो ग्राहक ऐप डाउनलोड के बारे में सूचित करने के लिए लैंडिंग पृष्ठ पर दिखाई देगा।',
  'Allow this option to display the Earn Money Section on the landing page.' => 'इस विकल्प को लैंडिंग पृष्ठ पर पैसा कमाएँ अनुभाग प्रदर्शित करने की अनुमति दें।',
  'Set a title and subtitle that will appear on the landing page to inform about driver app downloads.' => 'एक शीर्षक और उपशीर्षक सेट करें जो ड्राइवर ऐप डाउनलोड के बारे में सूचित करने के लिए लैंडिंग पृष्ठ पर दिखाई देगा।',
  'Ride Completed ' => 'सवारी पूरी हुई ',
  'Share Your Ride' => 'अपनी सवारी साझा करें',
  'Please turn on Face Verification Api status first' => 'कृपया पहले फेस वेरिफिकेशन एपीआई स्टेटस चालू करें',
  'Define when identity verification will be required for drivers.' => 'परिभाषित करें कि ड्राइवरों के लिए पहचान सत्यापन की आवश्यकता कब होगी।',
  'Drivers need to verify their identity as part of the registration process.' => 'पंजीकरण प्रक्रिया के भाग के रूप में ड्राइवरों को अपनी पहचान सत्यापित करने की आवश्यकता है।',
  'Drivers need to confirm their identity again after a set period of time.' => 'निर्धारित समयावधि के बाद ड्राइवरों को फिर से अपनी पहचान की पुष्टि करनी होगी।',
  'Drivers will be able to verify their identity again after a specific time frame.' => 'एक निश्चित समय सीमा के बाद ड्राइवर दोबारा अपनी पहचान सत्यापित कर सकेंगे।',
  'How AI Configuration Works' => 'AI कॉन्फ़िगरेशन कैसे काम करता है',
  'AI Configuration connects your system with OpenAI services.' => 'AI कॉन्फ़िगरेशन आपके सिस्टम को OpenAI सेवाओं से जोड़ता है।',
  'Once enabled, AI features such as content suggestions, smart responses, data analysis, or automation tools become available across the platform.' => 'एक बार सक्षम होने पर, सामग्री सुझाव, स्मार्ट प्रतिक्रिया, डेटा विश्लेषण, या स्वचालन उपकरण जैसी एआई सुविधाएँ पूरे प्लेटफ़ॉर्म पर उपलब्ध हो जाती हैं।',
  'How to Configure AI Setup' => 'एआई सेटअप को कैसे कॉन्फ़िगर करें',
  'Allow the option to activate AI services.' => 'AI सेवाओं को सक्रिय करने के विकल्प को अनुमति दें।',
  'Add your valid OpenAI API Key to authorize AI requests from the system.' => 'सिस्टम से AI अनुरोधों को अधिकृत करने के लिए अपनी वैध OpenAI API कुंजी जोड़ें।',
  'Enter your OpenAI Organization ID to associate usage with the correct OpenAI account.' => 'उपयोग को सही OpenAI खाते से जोड़ने के लिए अपनी OpenAI संगठन आईडी दर्ज करें।',
  'Save to apply the setup and start using AI-powered features.' => 'सेटअप लागू करने और AI-संचालित सुविधाओं का उपयोग शुरू करने के लिए सहेजें।',
  'Ensure the API Key and Organization ID are valid and active.' => 'सुनिश्चित करें कि एपीआई कुंजी और संगठन आईडी वैध और सक्रिय हैं।',
  'Are you sure to turn on this solution' => 'क्या आप निश्चित रूप से इस समाधान को चालू करेंगे?',
  'Once you turn On this solution' => 'एक बार जब आप इस समाधान को चालू कर दें',
  ', the landing page will have this solution.' => ', लैंडिंग पृष्ठ पर यह समाधान होगा।',
  'Login Settings' => 'लॉगिन सेटिंग्स',
  'Login Setup' => 'लॉगिन सेटअप',
  'The option you select customer will have the to option to login' => 'आप जिस विकल्प का चयन करेंगे ग्राहक के पास लॉगइन करने का विकल्प होगा',
  'Customer Login Options' => 'ग्राहक लॉगिन विकल्प',
  'Based on your selection, customers will have the options to login customer app' => 'आपके चयन के आधार पर, ग्राहकों के पास ग्राहक ऐप लॉगिन करने के विकल्प होंगे',
  'Customer & Driver Real-time location share' => 'ग्राहक और ड्राइवर वास्तविक समय स्थान साझा करें',
  'Allow Customer & Driver to share their live location during the trip' => 'यात्रा के दौरान ग्राहक और ड्राइवर को अपना लाइव स्थान साझा करने की अनुमति दें',
  'Real-time location share option' => 'वास्तविक समय स्थान साझा करने का विकल्प',
  'Driver Face Verification confirms a driver’s identity by matching their live facial image with the registered profile photo.' => 'ड्राइवर फेस वेरिफिकेशन, पंजीकृत प्रोफ़ाइल फोटो के साथ उनके चेहरे की लाइव छवि का मिलान करके ड्राइवर की पहचान की पुष्टि करता है।',
  'This ensures only approved drivers can access the platform and accept trips.' => 'यह सुनिश्चित करता है कि केवल अनुमोदित ड्राइवर ही प्लेटफ़ॉर्म तक पहुंच सकते हैं और यात्राएं स्वीकार कर सकते हैं।',
  'Admin configures the face verification service by selecting the region and adding Access Key and Secret Key.' => 'व्यवस्थापक क्षेत्र का चयन करके और एक्सेस कुंजी और गुप्त कुंजी जोड़कर चेहरा सत्यापन सेवा को कॉन्फ़िगर करता है।',
  'Manual Login' => 'मैनुअल लॉगिन',
  'Customers will get the option to create an account and log in using the necessary credentials & password in the app' => 'ग्राहकों को ऐप में खाता बनाने और आवश्यक क्रेडेंशियल और पासवर्ड का उपयोग करके लॉग इन करने का विकल्प मिलेगा',
  'OTP Login' => 'ओटीपी लॉगिन',
  'With OTP Login, customers can log in using their phone number without password. To enable this feature' => 'ओटीपी लॉगिन के साथ, ग्राहक बिना पासवर्ड के अपने फोन नंबर का उपयोग करके लॉग इन कर सकते हैं। इस सुविधा को सक्षम करने के लिए',
  'Configure SMS Setup' => 'एसएमएस सेटअप कॉन्फ़िगर करें',
  'Here.' => 'यहाँ.',
