  'With OTP Login, driver can log in using their phone number without password. To enable this feature' => 'ओटीपी लॉगिन के साथ, ड्राइवर बिना पासवर्ड के अपने फोन नंबर का उपयोग करके लॉग इन कर सकता है। इस सुविधा को सक्षम करने के लिए',
  'User Number Verification' => 'उपयोगकर्ता संख्या सत्यापन',
  'User must verify their number after signup manually.' => 'उपयोगकर्ता को साइनअप के बाद मैन्युअल रूप से अपना नंबर सत्यापित करना होगा।',
