  'Client key should have enable map javascript api and you can restrict it with http refer . Server key should have enable place api key and you can restrict it with ip . You can use same api for both field without any restrictions.' => 'क्लाइंट कुंजी में मैप जावास्क्रिप्ट एपीआई सक्षम होना चाहिए और आप इसे http रेफरेंस के साथ प्रतिबंधित कर सकते हैं। सर्वर कुंजी में प्लेस एपीआई कुंजी सक्षम होनी चाहिए और आप इसे आईपी के साथ प्रतिबंधित कर सकते हैं। आप बिना किसी प्रतिबंध के दोनों क्षेत्रों के लिए एक ही एपीआई का उपयोग कर सकते हैं।',
  'Google Maps' => 'गूगल मैप्स',
