  'OpenStreetMap (OSM)setup' => 'ओपनस्ट्रीटमैप (ओएसएम) सेटअप',
  'Set up the api configuration forOpenStreetMap (OSM).' => 'OpenStreetMap (OSM) के लिए एपीआई कॉन्फ़िगरेशन सेट करें।',
