  'At least one social media must remain active for login. Otherwise social media login cannot work.' => 'लॉगिन के लिए कम से कम एक सोशल मीडिया एक्टिव रहना चाहिए। अन्यथा सोशल मीडिया लॉगिन काम नहीं कर सकता.',
  '{provider} is currently disabled from configure 3rd party social login options.' => ':provider वर्तमान में कॉन्फ़िगर तृतीय पक्ष सामाजिक लॉगिन विकल्पों से अक्षम है।',
  'Enabling Google Login, customers can log in to the site using their existing Gmail credentials.' => 'Google लॉगिन सक्षम करके, ग्राहक अपने मौजूदा जीमेल क्रेडेंशियल का उपयोग करके साइट पर लॉग इन कर सकते हैं।',
  'Enabling Facebook Login, customers can log in to the site using their existing Facebook credentials.' => 'फेसबुक लॉगिन सक्षम करके, ग्राहक अपने मौजूदा फेसबुक क्रेडेंशियल्स का उपयोग करके साइट पर लॉग इन कर सकते हैं।',
  'Enabling Apple Login, customers can log in to the site using their existing Apple login credentials, Only for Apple devices.' => 'Apple लॉगिन सक्षम करके, ग्राहक अपने मौजूदा Apple लॉगिन क्रेडेंशियल का उपयोग करके साइट पर लॉग इन कर सकते हैं, केवल Apple उपकरणों के लिए।',
  'Google API Setup Instructions' => 'Google API सेटअप निर्देश',
  'Apple API Setup Instructions' => 'एप्पल एपीआई सेटअप निर्देश',
  'Sign in to your Apple Developer account and open Certificates, Identifiers & Profiles.' => 'अपने Apple डेवलपर खाते में साइन इन करें और प्रमाणपत्र, पहचानकर्ता और प्रोफ़ाइल खोलें।',
  'Copy your Team ID from the top-right of the Membership page and paste it into the Team id field.' => 'सदस्यता पृष्ठ के ऊपर दाईं ओर से अपनी टीम आईडी कॉपी करें और टीम आईडी फ़ील्ड में पेस्ट करें।',
  'Open Identifiers, register or select an App ID, and enable the Sign in with Apple capability.' => 'पहचानकर्ता खोलें, रजिस्टर करें या एक ऐप आईडी चुनें, और ऐप्पल क्षमता के साथ साइन इन सक्षम करें।',
  'Copy the Bundle ID of that App ID and paste it into the Store Bundle ID field.' => 'उस ऐप आईडी की बंडल आईडी को कॉपी करें और स्टोर बंडल आईडी फ़ील्ड में पेस्ट करें।',
  'Open Keys, create a new key with Sign in with Apple enabled, and copy its Key ID into the Store Client Secret Key field.' => 'कुंजियाँ खोलें, ऐप्पल सक्षम के साथ साइन इन के साथ एक नई कुंजी बनाएं, और इसकी कुंजी आईडी को स्टोर क्लाइंट सीक्रेट कुंजी फ़ील्ड में कॉपी करें।',
  'Download the AuthKey file (.p8), upload it in the Choose updated file field, and store it safely as it can be downloaded only once.' => 'AuthKey फ़ाइल (.p8) डाउनलोड करें, इसे अद्यतन फ़ाइल चुनें फ़ील्ड में अपलोड करें, और इसे सुरक्षित रूप से संग्रहीत करें क्योंकि इसे केवल एक बार डाउनलोड किया जा सकता है।',
  'Turn on the switch and click Save.' => 'स्विच चालू करें और सहेजें पर क्लिक करें।',
  'The Bundle ID is required when Apple login is active.' => 'Apple लॉगिन सक्रिय होने पर बंडल आईडी की आवश्यकता होती है।',
  'The Key ID is required when Apple login is active.' => 'Apple लॉगिन सक्रिय होने पर कुंजी आईडी आवश्यक है।',
  'The Team ID is required when Apple login is active.' => 'Apple लॉगिन सक्रिय होने पर टीम आईडी की आवश्यकता होती है।',
  'The AuthKey (.p8) file is required when Apple login is active.' => 'Apple लॉगिन सक्रिय होने पर AuthKey (.p8) फ़ाइल की आवश्यकता होती है।',
  'The uploaded file must be a .p8 AuthKey file.' => 'अपलोड की गई फ़ाइल एक .p8 AuthKey फ़ाइल होनी चाहिए।',
  'The uploaded file is not a valid AuthKey (.p8) private key file.' => 'अपलोड की गई फ़ाइल मान्य AuthKey (.p8) निजी कुंजी फ़ाइल नहीं है।',
  'A key file has been uploaded.' => 'एक कुंजी फ़ाइल अपलोड कर दी गई है.',
  'Facebook API Setup Instructions' => 'फेसबुक एपीआई सेटअप निर्देश',
  'Go to the Google Developers Console.' => 'Google डेवलपर्स कंसोल पर जाएं.',
  'Create a new project or select an existing project.' => 'एक नया प्रोजेक्ट बनाएं या किसी मौजूदा प्रोजेक्ट का चयन करें।',
  'Click on Credentials in the left-hand menu.' => 'बाएँ हाथ के मेनू में क्रेडेंशियल्स पर क्लिक करें।',
  'Create an OAuth client ID for a web application.' => 'वेब एप्लिकेशन के लिए OAuth क्लाइंट आईडी बनाएं।',
  'Enter a name for your client ID and click Create.' => 'अपनी क्लाइंट आईडी के लिए एक नाम दर्ज करें और क्रिएट पर क्लिक करें।',
  'Enter the URL of your website as an authorized JavaScript origin.' => 'अपनी वेबसाइट का URL अधिकृत जावास्क्रिप्ट मूल के रूप में दर्ज करें।',
  'Enter the callback URL as an authorized redirect URL.' => 'कॉलबैक यूआरएल को अधिकृत रीडायरेक्ट यूआरएल के रूप में दर्ज करें।',
  'Copy and paste the client ID and client secret into your application settings.' => 'क्लाइंट आईडी और क्लाइंट सीक्रेट को कॉपी करके अपनी एप्लिकेशन सेटिंग में पेस्ट करें।',
  'Enable the Google login option in your application settings and thoroughly test the integration before deploying it to a live environment.' => 'अपनी एप्लिकेशन सेटिंग में Google लॉगिन विकल्प सक्षम करें और इसे लाइव वातावरण में तैनात करने से पहले एकीकरण का पूरी तरह से परीक्षण करें।',
  'Go to apple developer page' => 'ऐप्पल डेवलपर पेज पर जाएं',
  'Click here' => 'यहां क्लिक करें',
  'In the top left corner you can see the Team ID [Apple developer account name] - Team ID.' => 'ऊपरी बाएँ कोने में आप टीम आईडी [Apple डेवलपर खाता नाम] - टीम आईडी देख सकते हैं।',
  'Click plus icon, select App IDs, then click on continue.' => 'प्लस आइकन पर क्लिक करें, ऐप आईडी चुनें, फिर जारी रखें पर क्लिक करें।',
  'Put a description and also identifier (identifier that used for app) and this is the Client ID.' => 'एक विवरण और पहचानकर्ता (पहचानकर्ता जो ऐप के लिए उपयोग किया जाता है) डालें और यह क्लाइंट आईडी है।',
  'Click continue and download the file in device named AuthKey ID.p8 (store it safely and it is used for push notification).' => 'जारी रखें पर क्लिक करें और AuthKey ID.p8 नामक डिवाइस में फ़ाइल डाउनलोड करें (इसे सुरक्षित रूप से संग्रहीत करें और इसका उपयोग पुश अधिसूचना के लिए किया जाता है)।',
  'Again click plus icon, select Service IDs, then click on continue.' => 'फिर से प्लस आइकन पर क्लिक करें, सर्विस आईडी चुनें, फिर जारी रखें पर क्लिक करें।',
  'Put a description and also identifier and continue.' => 'एक विवरण और पहचानकर्ता डालें और जारी रखें।',
  'Download the file in device named AuthKey KeyID.p8 (this is the service key ID file and also after AuthKey that is the key ID).' => 'AuthKey KeyID.p8 नामक डिवाइस में फ़ाइल डाउनलोड करें (यह सेवा कुंजी आईडी फ़ाइल है और AuthKey के बाद भी कुंजी आईडी है)।',
  'Go to the Facebook Developer website.' => 'फेसबुक डेवलपर वेबसाइट पर जाएं।',
  'Create a new app or select an existing app.' => 'एक नया ऐप बनाएं या किसी मौजूदा ऐप का चयन करें।',
  'Click on Add a New App or select an existing app from the dashboard.' => 'एक नया ऐप जोड़ें पर क्लिक करें या डैशबोर्ड से किसी मौजूदा ऐप का चयन करें।',
  'Fill in the required details, such as Display Name, Contact Email, and App Purpose.' => 'आवश्यक विवरण भरें, जैसे प्रदर्शन नाम, संपर्क ईमेल और ऐप उद्देश्य।',
  'Click Create App to create your app.' => 'अपना ऐप बनाने के लिए क्रिएट ऐप पर क्लिक करें।',
  'In the left-hand menu, click on Settings and then Basic to access your app basic settings.' => 'अपने ऐप की बुनियादी सेटिंग्स तक पहुंचने के लिए बाएं हाथ के मेनू में सेटिंग्स और फिर बेसिक पर क्लिक करें।',
  'Scroll down to the Facebook Login section and click on Set Up to configure your Facebook login settings.' => 'फेसबुक लॉगिन अनुभाग तक नीचे स्क्रॉल करें और अपनी फेसबुक लॉगिन सेटिंग्स को कॉन्फ़िगर करने के लिए सेट अप पर क्लिक करें।',
  'Choose the login behavior, permissions, and other settings as per your requirements.' => 'अपनी आवश्यकताओं के अनुसार लॉगिन व्यवहार, अनुमतियाँ और अन्य सेटिंग्स चुनें।',
  'Copy and paste the App ID and App Secret into your application settings.' => 'ऐप आईडी और ऐप सीक्रेट को कॉपी करके अपनी एप्लिकेशन सेटिंग में पेस्ट करें।',
  'Enable the Facebook login option in your applications settings and thoroughly test the integration before deploying it to a live environment.' => 'अपनी एप्लिकेशन सेटिंग में फेसबुक लॉगिन विकल्प सक्षम करें और इसे लाइव वातावरण में तैनात करने से पहले एकीकरण का पूरी तरह से परीक्षण करें।',
  'Team id' => 'टीम आईडी',
  'Ex: Team id' => 'उदाहरणार्थ: टीम आईडी',
  'Ex: Key ID' => 'उदाहरण: कुंजी आईडी',
  'Choose updated file' => 'अद्यतन फ़ाइल चुनें',
  'Enter your iOS app Bundle ID from your Apple developer account.' => 'अपने Apple डेवलपर खाते से अपना iOS ऐप बंडल आईडी दर्ज करें।',
  'Enter your Apple Developer Team ID from your Apple developer account.' => 'अपने Apple डेवलपर खाते से अपनी Apple डेवलपर टीम आईडी दर्ज करें।',
  'Enter the Key ID of your Apple service key.' => 'अपनी Apple सेवा कुंजी की कुंजी आईडी दर्ज करें।',
  'Enter the Client Secret generated for your OAuth application.' => 'अपने OAuth एप्लिकेशन के लिए जेनरेट किया गया क्लाइंट सीक्रेट दर्ज करें।',
  'Set notification verify driver identity before customer start trip' => 'ग्राहक की यात्रा शुरू करने से पहले अधिसूचना सेट करें ड्राइवर की पहचान सत्यापित करें',
  'Verify Driver Identity' => 'ड्राइवर की पहचान सत्यापित करें',
  'Write a message' => 'एक संदेश लिखें',
  'For safety, check your driver identity & vehicle number before start the trip.' => 'सुरक्षा के लिए, यात्रा शुरू करने से पहले अपने ड्राइवर की पहचान और वाहन नंबर की जांच करें।',
  'Enable Smart Rebooking' => 'स्मार्ट रीबुकिंग सक्षम करें',
  'Enable Destination Mode' => 'गंतव्य मोड सक्षम करें',
  'Maximum Usage Limit' => 'अधिकतम उपयोग सीमा',
  'Set the maximum number of times a customer can use destination mode.' => 'यह निर्धारित करें कि कोई ग्राहक अधिकतम कितनी बार गंतव्य मोड का उपयोग कर सकता है।',
  'Auto Arrival Notification' => 'स्वत: आगमन अधिसूचना',
  'Allow Send Auto Arrival Notification for Customer & Driver' => 'ग्राहक और ड्राइवर के लिए ऑटो आगमन अधिसूचना भेजने की अनुमति दें',
  'Set How Many Minutes Before Auto Arrival Notification Show' => 'स्वतः आगमन अधिसूचना शो से कितने मिनट पहले सेट करें',
  'Set how many minutes before arrival the notification should be sent.' => 'निर्धारित करें कि आगमन से कितने मिनट पहले अधिसूचना भेजी जानी चाहिए।',
  'Set auto arrival notification for customer & driver' => 'ग्राहक और ड्राइवर के लिए ऑटो आगमन अधिसूचना सेट करें',
  'Driver is Nearby (For Customer)' => 'ड्राइवर पास में है (ग्राहक के लिए)',
  'Message sent to the customer when the driver is nearby.' => 'ड्राइवर के पास होने पर ग्राहक को संदेश भेजा जाता है।',
  'Almost at pickup point (For Driver)' => 'लगभग पिकअप प्वाइंट पर (ड्राइवर के लिए)',
  'Message sent to the driver when close to the pickup point.' => 'पिकअप पॉइंट के करीब होने पर ड्राइवर को संदेश भेजा गया।',
  'Driver is Nearby' => 'ड्राइवर पास में है',
  'Almost at pickup point' => 'लगभग पिकअप पॉइंट पर',
  'Use :placeholder to display minutes' => 'मिनट प्रदर्शित करने के लिए :प्लेसहोल्डर का उपयोग करें',
  'Driver Identity Verification' => 'ड्राइवर की पहचान सत्यापन',
  'Verify driver identity before start trip' => 'यात्रा शुरू करने से पहले ड्राइवर की पहचान सत्यापित करें',
  'Enable Identity Verification' => 'पहचान सत्यापन सक्षम करें',
  'Smart Rebooking' => 'स्मार्ट रीबुकिंग',
  'Automatically rebook trips by sending requests to nearby drivers if a cancellation occurs.' => 'रद्दीकरण होने पर आस-पास के ड्राइवरों को अनुरोध भेजकर स्वचालित रूप से यात्राएं दोबारा बुक करें।',
  'Destination Mode' => 'गंतव्य मोड',
  'Allow users to choose their preferred route to reach their destination.' => 'उपयोगकर्ताओं को अपने गंतव्य तक पहुंचने के लिए अपना पसंदीदा मार्ग चुनने की अनुमति दें।',
  'Set the maximum number of times a customer can update destination.' => 'यह निर्धारित करें कि कोई ग्राहक अधिकतम कितनी बार गंतव्य को अपडेट कर सकता है।',
  'Ex : 5' => 'उदाहरण : 5',
  'Please add a message before enabling Driver Identity Verification.' => 'कृपया ड्राइवर पहचान सत्यापन सक्षम करने से पहले एक संदेश जोड़ें।',
  'Please set the maximum usage limit before enabling Destination Mode.' => 'कृपया गंतव्य मोड सक्षम करने से पहले अधिकतम उपयोग सीमा निर्धारित करें।',
  'Please set the notification time before enabling Auto Arrival Notification.' => 'कृपया स्वतः आगमन अधिसूचना सक्षम करने से पहले अधिसूचना समय निर्धारित करें।',
  'Please add the customer message before enabling Auto Arrival Notification.' => 'कृपया ऑटो आगमन अधिसूचना सक्षम करने से पहले ग्राहक संदेश जोड़ें।',
  'Please add the driver message before enabling Auto Arrival Notification.' => 'कृपया ऑटो आगमन अधिसूचना सक्षम करने से पहले ड्राइवर संदेश जोड़ें।',
  'Settings successfully updated' => 'सेटिंग्स सफलतापूर्वक अपडेट की गईं',
  'Please set the increase fare amount before enabling fare increase.' => 'कृपया किराया वृद्धि सक्षम करने से पहले बढ़ी हुई किराया राशि निर्धारित करें।',
  'Cancelled by Customer' => 'ग्राहक द्वारा रद्द किया गया',
  'Cancellation Reason' => 'रद्द करने का कारण',
  'View In Map' => 'मानचित्र में देखें',
  'Your account is suspended, so you cannot start a trip right now.' => 'आपका खाता निलंबित कर दिया गया है, इसलिए आप अभी यात्रा शुरू नहीं कर सकते।',
  'Are you sure to pause the driver status' => 'क्या आप निश्चित रूप से ड्राइवर स्थिति को रोकना चाहते हैं?',
  'The driver is blocked from login and dispatch until the suspension is removed.' => 'निलंबन हटाए जाने तक ड्राइवर को लॉगिन और प्रेषण से अवरुद्ध कर दिया गया है।',
  'Account is suspended.' => 'खाता निलंबित कर दिया गया है.',
  'Admin approved your registration. You can login now.' => 'व्यवस्थापक ने आपके पंजीकरण को मंजूरी दे दी. अब आप लॉगइन कर सकते हैं.',
  'Once suspended, the driver is blocked from login and dispatch until the suspension is removed.' => 'एक बार निलंबित होने के बाद, निलंबन हटाए जाने तक ड्राइवर को लॉगिन और प्रेषण से अवरुद्ध कर दिया जाता है।',
  'The driver will regain login access and start receiving trip requests again.' => 'ड्राइवर लॉगिन एक्सेस पुनः प्राप्त कर लेगा और यात्रा अनुरोध फिर से प्राप्त करना शुरू कर देगा।',
  'Are you sure want to un-suspend the driver' => 'क्या आप वाकई ड्राइवर का निलंबन रद्द करना चाहते हैं?',
  'driver_status_paused' => 'ड्राइवर स्थिति रोक दी गई',
  'Your status has been paused by admin. You cannot go online until the pause ends.' => 'आपका स्टेटस एडमिन द्वारा रोक दिया गया है. जब तक रोक समाप्त नहीं होती तब तक आप ऑनलाइन नहीं हो सकते।',
  'Driver status paused successfully' => 'ड्राइवर स्थिति सफलतापूर्वक रुकी',
  'Driver status resumed successfully' => 'ड्राइवर स्थिति सफलतापूर्वक फिर से शुरू हुई',
  'You cannot change the status of a suspended driver' => 'आप निलंबित ड्राइवर की स्थिति नहीं बदल सकते',
  'day' => 'दिन',
  'This driver is paused for {duration}.' => 'यह ड्राइवर :duration के लिए रुका हुआ है।',
  'Reason : {reason}' => 'कारण: :reason',
  'Are you sure want to resume the driver status' => 'क्या आप वाकई ड्राइवर स्थिति फिर से शुरू करना चाहते हैं?',
  'The driver can go online and receive trip requests again.' => 'ड्राइवर ऑनलाइन जा सकता है और यात्रा अनुरोध दोबारा प्राप्त कर सकता है।',
  'Resume' => 'बायोडाटा',
  'Your account is under review' => 'आपका खाता समीक्षाधीन है',
  'Setup notification to drivers for status pause and resume updates.' => 'स्टेटस पॉज़ और अपडेट फिर से शुरू करने के लिए ड्राइवरों को सेटअप अधिसूचना।',
  'Setup notifications sent to drivers for status and other account related updates in different cases.' => 'विभिन्न मामलों में स्थिति और अन्य खाता संबंधी अपडेट के लिए ड्राइवरों को सेटअप सूचनाएं भेजी गईं।',
  'Your status has been paused for {pauseDuration} by admin. You cannot go online until the pause ends.' => 'आपकी स्थिति व्यवस्थापक द्वारा :pauseDuration के लिए रोक दी गई है। जब तक रोक समाप्त नहीं होती तब तक आप ऑनलाइन नहीं हो सकते।',
  'year' => 'वर्ष',
  'years' => 'साल',
  'paused' => 'रुका हुआ',
  'Driver is suspended' => 'ड्राइवर को निलंबित कर दिया गया है',
  'suspended' => 'निलंबित',
  'Connect_the_last_dot_to_the_first_dot_to_close_the_polygon_before_saving' => 'सहेजने से पहले बहुभुज को बंद करने के लिए अंतिम बिंदु को पहले बिंदु से कनेक्ट करें',
  'suspended_driver' => 'निलंबित ड्राइवर',
  'searching_for_rider' => 'सवार की तलाश की जा रही है',
  'Setup miscellaneous notifications sent to customers that do not fall under the other categories.' => 'सेटअप विविध सूचनाएं उन ग्राहकों को भेजी जाती हैं जो अन्य श्रेणियों के अंतर्गत नहीं आते हैं।',
  'Setup miscellaneous notifications sent to drivers that do not fall under the other categories.' => 'सेटअप विविध सूचनाएं उन ड्राइवरों को भेजी जाती हैं जो अन्य श्रेणियों के अंतर्गत नहीं आते हैं।',
  'Driver is paused for exceeding the cash-in-hand limit. Collect the cash to resume.' => 'कैश-इन-हैंड सीमा से अधिक होने पर ड्राइवर को रोक दिया जाता है। फिर से शुरू करने के लिए नकदी एकत्र करें।',
  'Driver is paused for face verification failure. Verify the driver identity to resume.' => 'चेहरे का सत्यापन विफल होने के कारण ड्राइवर को रोक दिया गया है। फिर से शुरू करने के लिए ड्राइवर की पहचान सत्यापित करें।',
  'Your face verification has failed and your status has been paused. Please verify your identity again to go online.' => 'आपके चेहरे का सत्यापन विफल हो गया है और आपकी स्थिति रोक दी गई है। कृपया ऑनलाइन होने के लिए अपनी पहचान दोबारा सत्यापित करें।',
  'Your limit to hold cash in hand has been exceeded. Please pay the due to admin from your wallet page.' => 'हाथ में नकदी रखने की आपकी सीमा पार हो गई है। कृपया अपने वॉलेट पेज से व्यवस्थापक को देय राशि का भुगतान करें।',
  'Turn off same time for every day to set a specific day' => 'एक विशिष्ट दिन निर्धारित करने के लिए प्रत्येक दिन के लिए समान समय बंद करें',
  'Schedule not found' => 'शेड्यूल नहीं मिला',
  'Successfully deleted information' => 'जानकारी सफलतापूर्वक हटा दी गई',
  'test' => 'परीक्षण',
  'The action field is required.' => 'क्रिया क्षेत्र आवश्यक है.',
  'Another driver already accepted the trip request.' => 'एक अन्य ड्राइवर ने पहले ही यात्रा अनुरोध स्वीकार कर लिया है।',
  'did not match Driver Photo and Vehicle Model' => 'ड्राइवर फोटो और वाहन मॉडल से मेल नहीं खाता',
  'trip_canceled_for_driver_identity_mismatch' => 'ड्राइवर की पहचान बेमेल होने के कारण यात्रा रद्द कर दी गई',
  'Driver Photo' => 'ड्राइवर फोटो',
  'list_separator' => 'सूची विभाजक',
  'Your trip has been canceled because the driver did not match {reason}.' => 'आपकी यात्रा रद्द कर दी गई है क्योंकि ड्राइवर :reason से मेल नहीं खाता।',
  'Setup notification for vehicle and identity approval messages to drivers.' => 'वाहन के लिए सेटअप अधिसूचना और ड्राइवरों को पहचान अनुमोदन संदेश।',
  'Clear_drawing' => 'स्पष्ट रेखांकन',
  'Are you sure to delete this Refund Reason' => 'क्या आप निश्चित रूप से इस धनवापसी कारण को हटा देंगे',
  'Click_to_close_polygon' => 'बहुभुज को बंद करने के लिए क्लिक करें',
);
